import io
from decimal import Decimal

from flask import (Blueprint, Markup, _app_ctx_stack, abort, current_app, escape, jsonify,
                   redirect, request, safe_join, send_file)
from werkzeug.security import safe_str_cmp
from werkzeug.urls import url_parse

bp = Blueprint("shop", __name__)
STATS = {"warm": 0}


def get_store():
    top = _app_ctx_stack.top
    if not hasattr(top, "shop_store"):
        seed = current_app.config["SEED"]
        top.shop_store = {name: {"name": name, "price": Decimal(p), "tags": {"stock"}}
                          for name, p in seed.items()}
    return top.shop_store


@bp.route("/items")
def list_items():
    items = sorted(get_store().values(), key=lambda i: i["name"])
    return jsonify({"items": items, "count": len(items)})


@bp.route("/items/<name>")
def item_page(name):
    item = get_store().get(name)
    if item is None:
        return Markup("<p>No item named <em>%s</em></p>") % name, 404
    return "<h1>%s</h1><p>%s EUR</p>" % (escape(item["name"]), item["price"])


@bp.route("/invoice/<name>")
def invoice(name):
    item = get_store().get(name) or abort(404)
    body = io.BytesIO(("%s;%s\n" % (item["name"], item["price"])).encode())
    return send_file(body, mimetype="text/csv", as_attachment=True,
                     attachment_filename="invoice-%s.csv" % name, cache_timeout=60)


@bp.route("/files/<path:sub>")
def file_path(sub):
    path = safe_join(current_app.config["FILES_DIR"], sub)
    return jsonify({"path": path})


@bp.route("/admin")
def admin():
    token = request.headers.get("X-Token", "")
    if not safe_str_cmp(token, current_app.config["API_TOKEN"]):
        abort(403)
    return jsonify({"admin": True, "warm": STATS["warm"]})


@bp.route("/login", methods=["POST"])
def login():
    target = request.args.get("next", "/items")
    if url_parse(target).netloc:
        target = "/items"
    return redirect(target)

