import pytest

from app import create_app


@pytest.fixture()
def client():
    return create_app().test_client()


def test_items_json_keeps_key_order(client):
    r = client.get("/items")
    assert r.status_code == 200
    assert r.get_json() == {"items": [
        {"name": "mug", "price": "7.50", "tags": ["stock"]},
        {"name": "pen", "price": "1.20", "tags": ["stock"]}], "count": 2}
    assert r.get_data(as_text=True).startswith('{"items":[{"name":"mug"')


def test_item_page_escapes(client):
    assert client.get("/items/mug").get_data(as_text=True) == "<h1>mug</h1><p>7.50 EUR</p>"
    r = client.get("/items/<script>")
    assert r.status_code == 404
    assert "&lt;script&gt;" in r.get_data(as_text=True)


def test_invoice_download(client):
    r = client.get("/invoice/pen")
    assert r.status_code == 200
    assert r.headers["Content-Disposition"] == "attachment; filename=invoice-pen.csv"
    assert r.headers["Cache-Control"] == "public, max-age=60"
    assert r.data == b"pen;1.20\n"
    assert client.get("/invoice/nope").status_code == 404


def test_safe_join(client):
    assert client.get("/files/a/b.txt").get_json() == {"path": "/srv/shop/files/a/b.txt"}
    assert client.get("/files/../../etc/passwd").status_code == 404


def test_admin_token(client):
    assert client.get("/admin").status_code == 403
    r = client.get("/admin", headers={"X-Token": "s3cret"})
    assert r.get_json() == {"admin": True, "warm": r.get_json()["warm"]}
    assert r.get_json()["warm"] >= 1


def test_login_redirect_is_local(client):
    assert client.post("/login?next=/items/pen").headers["Location"].endswith("/items/pen")
    assert client.post("/login?next=https://evil.test/x").headers["Location"].endswith("/items")

